// update sources: 'nstrang' is 0 for the first Strang step and 1 for
// the second step
struct gkyl_update_status
moment_coupling_update(
  gkyl_moment_app *app, struct moment_coupling *src, int nstrang, double tcurr, double dt
)
{
  int sidx[] = {0, app->ndim};
  struct gkyl_array *fluids[GKYL_MAX_SPECIES];
  const struct gkyl_array *app_accels[GKYL_MAX_SPECIES];
  const struct gkyl_array *pr_rhs_const[GKYL_MAX_SPECIES];
  const struct gkyl_array *nT_sources[GKYL_MAX_SPECIES];

  double dt_suggested = DBL_MAX;
  struct gkyl_ten_moment_grad_closure_status stat;

  for (int i = 0; i < app->num_species; ++i) {
    fluids[i] = app->species[i].f[sidx[nstrang]];

    if (app->species[i].app_accel_evolve) {
      gkyl_fv_proj_advance(
        app->species[i].app_accel_proj, tcurr, &app->local, app->species[i].app_accel
      );
    }
    app_accels[i] = app->species[i].app_accel;

    if (app->species[i].eqn_type == GKYL_EQN_TEN_MOMENT && app->species[i].has_grad_closure) {
      // Non-ideal variables are defined on an extended range with one additional "cell" in each direction.
      // This additional cell accounts for the fact that non-ideal variables are stored at cell vertices.
      stat = gkyl_ten_moment_grad_closure_advance(
        src->grad_closure_slvr[i], &src->non_ideal_local, &app->local,
        app->species[i].f[sidx[nstrang]], app->field.f[sidx[nstrang]], src->non_ideal_cflrate[i],
        dt, src->non_ideal_vars[i], src->pr_rhs[i]
      );

      if (!stat.success) {
        return (struct gkyl_update_status){.success = false, .dt_suggested = stat.dt_suggested};
      }

      dt_suggested = fmin(dt_suggested, stat.dt_suggested);
    }

    if (app->species[i].eqn_type == GKYL_EQN_TEN_MOMENT && app->species[i].has_nn_closure) {
      // Non-ideal variables are defined on an extended range with one additional "cell" in each direction.
      // This additional cell accounts for the fact that non-ideal variables are stored at cell vertices.
      gkyl_ten_moment_nn_closure_advance(
        src->nn_closure_slvr[i], &src->non_ideal_local, &app->local,
        app->species[i].f[sidx[nstrang]], app->field.f[sidx[nstrang]], src->non_ideal_vars[i],
        src->pr_rhs[i]
      );
    }
  }

  if (app->has_braginskii) {
    gkyl_moment_braginskii_advance(
      src->brag_slvr, src->non_ideal_local, app->local, fluids, app->field.f[sidx[nstrang]],
      src->non_ideal_cflrate, src->non_ideal_vars, src->pr_rhs
    );
  }

  if (app->field.ext_em_evolve) {
    gkyl_fv_proj_advance(app->field.ext_em_proj, tcurr, &app->local, app->field.ext_em);
  }

  if (app->field.app_current_evolve) {
    // Derived collision times
    tau[j][ELC] = calc_tau(
      1.0, bes->coll_fac, bes->epsilon0, q[ELC], q[ION], m[ELC], m[ION], rho[ION], T[j][ELC]
    );
    tau[j][ION] = calc_tau(
      1.0, sqrt(2.0) * bes->coll_fac, bes->epsilon0, q[ION], q[ION], m[ION], m[ION], rho[ION],
      T[j][ION]
    );

    // Brag-type enum is used to turn coefficients on/off in a branchless fashion
    bool electron_viscosity = (bes->param[ELC].type_brag & GKYL_BRAG_VISC);
    bool electron_heatFlux = (bes->param[ELC].type_brag & GKYL_BRAG_HEATFLUX);
    bool ion_viscosity = (bes->param[ION].type_brag & GKYL_BRAG_VISC);
    bool ion_heatFlux = (bes->param[ION].type_brag & GKYL_BRAG_HEATFLUX);

    eta_par[j][ELC] = electron_viscosity * 1.5 * 0.73 * p[ELC] * tau[j][ELC];
    eta_perp[j][ELC] =
      electron_viscosity * 0.51 * p[ELC] / (tau[j][ELC] * omega_c[ELC] * omega_c[ELC]);
    eta_cross[j][ELC] = electron_viscosity * 0.25 * p[ELC] / omega_c[ELC];
    kappa_par[j][ELC] = electron_heatFlux * 3.16 * p[ELC] * tau[j][ELC] / m[ELC];
    kappa_perp[j][ELC] =
      electron_heatFlux * 4.66 * p[ELC] / (m[ELC] * tau[j][ELC] * omega_c[ELC] * omega_c[ELC]);
    kappa_cross[j][ELC] = electron_heatFlux * 2.5 * p[ELC] / (m[ELC] * omega_c[ELC]);

    eta_par[j][ION] = ion_viscosity * 1.5 * 0.96 * p[ION] * tau[j][ION];
    eta_perp[j][ION] = ion_viscosity * 0.3 * p[ION] / (tau[j][ION] * omega_c[ION] * omega_c[ION]);
    eta_cross[j][ION] = ion_viscosity * 0.25 * p[ION] / omega_c[ION];
    kappa_par[j][ION] = ion_heatFlux * 3.91 * p[ION] * tau[j][ION] / m[ION];
    kappa_perp[j][ION] =
      ion_heatFlux * 2 * p[ION] / (m[ION] * tau[j][ION] * omega_c[ION] * omega_c[ION]);
    kappa_cross[j][ION] = ion_heatFlux * 2.5 * p[ION] / (m[ION] * omega_c[ION]);

    double thermal_par = electron_heatFlux * -0.71 *
                         p[ELC]; // Parallel thermal force coefficient (same for each species)
    double thermal_perp = electron_heatFlux * 1.5 * p[ELC] /
                          (omega_c[ELC] * tau[j][ELC]
                          ); // Perpendicular thermal force coefficient (same for each species)
    double b_dot_j = b[j][0] * (u[j][ION][0] - u[j][ELC][0]) +
                     b[j][1] * (u[j][ION][1] - u[j][ELC][1]) +
                     b[j][2] * (u[j][ION][2] - u[j][ELC][2]);
    current_par[j][0] = thermal_par * b[j][0] * b_dot_j;
    current_par[j][1] = thermal_par * b[j][1] * b_dot_j;
    current_par[j][2] = thermal_par * b[j][2] * b_dot_j;
    current_cross[j][0] = thermal_perp * (b[j][1] * (u[j][ION][2] - u[j][ELC][2]) -
                                          b[j][2] * (u[j][ION][1] - u[j][ELC][1]));
    current_cross[j][1] = thermal_perp * (b[j][2] * (u[j][ION][0] - u[j][ELC][0]) -
                                          b[j][0] * (u[j][ION][2] - u[j][ELC][2]));
    current_cross[j][2] = thermal_perp * (b[j][0] * (u[j][ION][1] - u[j][ELC][1]) -
                                          b[j][1] * (u[j][ION][0] - u[j][ELC][0]));
  }
}

